'use strict';
(()=>{
 const $=id=>document.getElementById(id),fmt=(n,d=2)=>n==null?'—':n.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const display=s=>s.replace('Paris Saint Germain','Paris Saint-Germain');
 const year=s=>s.replace('-','–');
 const COLORS=['#235c44','#a72d36','#b68723','#527eaf','#7b65a2'];
 let rows=[],meta={},config={},currentRows=[],metric='perGame';
 function metrics(data){const s=XG.summary(data),captions=[s.rate?display(s.rate.team):'No eligible teams',s.season?display(s.season.team):'No eligible teams','Distinct teams after filters','One row = one team in one season'];$('metrics').innerHTML=XG.LABELS.map((label,i)=>`<article class="metric"><div class="metric-label">${label}</div><div class="metric-value">${fmt(s.values[i],i<2?2:0)}</div><div class="metric-caption">${esc(captions[i])}</div></article>`).join('');return s;}
 function bars(id,teams,key,limit=10){const el=$(id),list=XG.rank(teams,key).slice(0,limit);if(!list.length){el.innerHTML='<div class="empty">No teams match these filters.<br>Try a wider search or reset the filters.</div>';return;}
  const width=630,left=160,right=48,top=20,rowH=32,height=top+list.length*rowH+30,max=Math.max(...list.map(t=>t[key]))*1.07,plot=width-left-right;
  let svg=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(key==='perGame'?'Team expected goals per game':'Team average expected goals per season')} ranking"><title>Team ranking</title>`;
  for(let i=0;i<=4;i++){const v=max*i/4,x=left+plot*i/4;svg+=`<line x1="${x}" y1="${top-6}" x2="${x}" y2="${height-26}" stroke="#e8ece6"/><text x="${x}" y="${height-7}" text-anchor="middle">${fmt(v,key==='perGame'?1:0)}</text>`;}
  list.forEach((t,i)=>{const y=top+i*rowH,w=t[key]/max*plot;svg+=`<g><title>${esc(display(t.team))}: ${fmt(t[key])}</title><text class="team-label" x="${left-12}" y="${y+15}" text-anchor="end">${esc(display(t.team))}</text><rect x="${left}" y="${y}" width="${w}" height="23" rx="3" fill="${i===0?'#235c44':'#cddfc9'}"/><text class="value" x="${left+w+7}" y="${y+15}">${fmt(t[key])}</text></g>`;});svg+='</svg>';el.innerHTML=svg;
 }
 function trend(data,teams,seasons,key='perGame'){
  const el=$('trend-chart'),legend=$('trend-legend'),topTeams=XG.rank(teams,key).slice(0,5);legend.innerHTML=topTeams.map((t,i)=>`<span><i style="background:${COLORS[i]}"></i>${esc(display(t.team))}</span>`).join('');if(!topTeams.length){el.innerHTML='<div class="empty">No matching team history to show.</div>';return;}
  const points=topTeams.map(t=>seasons.map(season=>{const r=data.find(r=>r.Team_ID===t.id&&r.Season===season);return r?(key==='perGame'?r.Total_xG/r.Matches_Played:r.Total_xG):null;}));
  const width=630,height=330,left=42,right=20,top=22,bottom=42,pw=width-left-right,ph=height-top-bottom,max=Math.max(1,...points.flat().filter(v=>v!==null))*1.12;
  const x=i=>seasons.length===1?left+pw/2:left+i*pw/(seasons.length-1),y=v=>top+ph-(v/max)*ph;
  let svg=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Season-by-season team ${key==='perGame'?'xG per game':'total xG'}"><title>Expected goals by season</title>`;
  for(let i=0;i<=4;i++){const v=max*i/4,yy=y(v);svg+=`<line x1="${left}" y1="${yy}" x2="${width-right}" y2="${yy}" stroke="#e8ece6"/><text x="${left-9}" y="${yy+4}" text-anchor="end">${fmt(v,key==='perGame'?1:0)}</text>`;}
  seasons.forEach((s,i)=>{svg+=`<text x="${x(i)}" y="${height-15}" text-anchor="middle">${year(s)}</text>`;});
  points.forEach((vals,j)=>{let path='';vals.forEach((v,i)=>{if(v===null){path+=' ';return;}path+=`${i===0||vals[i-1]===null?'M':'L'}${x(i)},${y(v)} `;});svg+=`<path d="${path}" fill="none" stroke="${COLORS[j]}" stroke-width="2.5" stroke-linecap="round"/>`;vals.forEach((v,i)=>{if(v!==null)svg+=`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="${COLORS[j]}" stroke="white" stroke-width="1.5"><title>${esc(display(topTeams[j].team))}, ${year(seasons[i])}: ${fmt(v)}</title></circle>`;});});svg+='</svg>';el.innerHTML=svg;
 }
 function agreement(summary){const vals=config.tableau_verified_values;const verified=Array.isArray(vals)&&vals.length===4&&vals.every(v=>typeof v==='number'&&Number.isFinite(v));$('agreement-table').innerHTML=`<div class="table-scroll"><table><thead><tr><th>Summary measure</th><th class="num">Website</th><th class="num">Tableau</th><th>Status</th></tr></thead><tbody>${XG.LABELS.map((label,i)=>{const same=verified&&Math.abs(summary.values[i]-vals[i])<(i<2?.005:1e-9);return `<tr><td>${label}</td><td class="num">${fmt(summary.values[i],i<2?2:0)}</td><td class="num">${verified?fmt(vals[i],i<2?2:0):'Not verified'}</td><td>${verified?(same?'Matches':'Difference — review required'):'Pending'}</td></tr>`;}).join('')}</tbody></table></div>`;
  if(config.tableau_url&&/^https:\/\/(public\.)?tableau\.com\//.test(config.tableau_url)){$('tableau-status').innerHTML=`<a href="${esc(config.tableau_url)}" target="_blank" rel="noopener">Open the Tableau Public dashboard ↗</a>${verified?' · Compare the table above using the stated default filters.':' · Values have not yet been independently verified.'}`;}
 }
 function report(){
  const selected=XG.filter(rows),s=metrics(selected),rate=XG.rank(s.teams,'perGame'),season=XG.rank(s.teams,'perSeason');
  $('hero-rate').textContent=fmt(s.rate.perGame);$('hero-team').textContent=display(s.rate.team);$('hero-scope').textContent=`${fmt(s.rate.matches,0)} league games · ${fmt(s.rate.xg)} total xG`;
  $('opening').innerHTML=`<strong>${esc(display(s.rate.team))} leads with ${fmt(s.rate.perGame)} xG per game across five seasons.</strong> ${esc(display(s.season.team))} also produces the highest average season total, at ${fmt(s.season.perSeason)} xG. For club performance analysts, use this team as a benchmark for sustained chance creation, then assess its tactics against the quality of domestic opposition.`;
  const gap=rate[0].perGame-rate[1].perGame;
  $('finding1-title').textContent=`${display(rate[0].team)} creates ${fmt(rate[0].perGame)} xG per game.`;
  $('finding1-copy').textContent=`Across ${fmt(rate[0].matches,0)} league games, ${display(rate[0].team)} generates ${fmt(rate[0].xg)} xG. Its ${fmt(rate[0].perGame)} xG per game exceeds second-ranked ${display(rate[1].team)} (${fmt(rate[1].perGame)}) by ${fmt(gap)} xG per game, or ${fmt(gap/rate[1].perGame*100,1)}%. The comparison includes ${s.teams.length} teams represented in all five seasons.`;
  $('finding2-title').textContent=`${display(season[0].team)} averages ${fmt(season[0].perSeason)} xG per season.`;
  $('finding2-copy').textContent=`${display(season[0].team)} ranks first in average seasonal volume, ahead of ${display(season[1].team)} at ${fmt(season[1].perSeason)} xG per season. The leader averages ${fmt(season[0].matches/season[0].seasonCount,0)} games per season, compared with ${fmt(season[1].matches/season[1].seasonCount,0)} for the runner-up. Dividing by games therefore remains essential for comparing chance-creation intensity.`;
  const winners=XG.SEASONS.map(season=>{const ts=XG.aggregate(selected.filter(r=>r.Season===season));return {season,rate:XG.rank(ts,'perGame')[0],volume:XG.rank(ts,'perSeason')[0]};});
  const unique=new Set(winners.map(w=>w.rate.id)),wins=winners.filter(w=>w.rate.id===s.rate.id).length,other=winners.find(w=>w.rate.id!==s.rate.id);
  $('finding3-title').textContent=`${display(s.rate.team)} leads per game in ${wins} of five seasons.`;
  $('finding3-copy').textContent=`The five-season leader also has the highest season xG per game in ${wins} of the five campaigns among the same eligible teams. ${other?`In ${year(other.season)}, ${display(other.rate.team)} leads at ${fmt(other.rate.perGame)} xG per game. `:''}${unique.size} ${unique.size===1?'club holds':'clubs share'} the five annual per-game leads. The trend chart shows whether strong attacking output persists rather than relying on a single campaign.`;
  bars('rate-chart',s.teams,'perGame');bars('season-chart',s.teams,'perSeason');trend(selected,s.teams,XG.SEASONS);
  $('year-winners').innerHTML=`<table><thead><tr><th>Season</th><th>Highest xG/game</th><th class="num">xG/game</th><th>Highest season xG</th><th class="num">xG</th></tr></thead><tbody>${winners.map(w=>`<tr><td>${year(w.season)}</td><td>${esc(display(w.rate.team))}</td><td class="num">${fmt(w.rate.perGame)}</td><td>${esc(display(w.volume.team))}</td><td class="num">${fmt(w.volume.xg)}</td></tr>`).join('')}</tbody></table>`;
  $('dataset-scope').textContent=`The source file contains ${rows.length} team-season records, ${new Set(rows.map(r=>r.Team_ID)).size} distinct teams, five leagues and five seasons. Each source league-season table contains complete 34- or 38-match records for its teams.`;
  $('eligibility-copy').textContent=`The report and default dashboard include ${selected.length} records for ${s.teams.length} teams present in all five seasons. The other ${rows.length-selected.length} team-season records remain in the CSV but are excluded from this balanced five-season comparison because their teams do not appear in every season. They become available when the coverage filter is disabled or a shorter period is chosen.`;
  $('retrieval-date').textContent=`Snapshot: ${new Date(meta.retrieved_at).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'America/Chicago'})}`;agreement(s);
 }
 function options(){let start=$('start-season').value,end=$('end-season').value;if(start>end){$('end-season').value=start;end=start;}return {seasons:XG.SEASONS.filter(s=>s>=start&&s<=end),league:$('league').value,team:$('team').value,complete:$('complete').checked};}
 function updateURL(opts){const p=new URLSearchParams();if(opts.seasons[0]!==XG.SEASONS[0])p.set('start',opts.seasons[0]);if(opts.seasons.at(-1)!==XG.SEASONS.at(-1))p.set('end',opts.seasons.at(-1));if(opts.league!=='all')p.set('league',opts.league);if(opts.team)p.set('team',opts.team);if(!opts.complete)p.set('coverage','any');if(metric!=='perGame')p.set('metric',metric);try{history.replaceState(null,'',location.pathname+(p.size?'?'+p.toString():''));}catch{}}
 function table(teams){const sort=$('table-sort').value,ts=sort==='team'?[...teams].sort((a,b)=>a.team.localeCompare(b.team)):XG.rank(teams,sort);$('data-table').innerHTML=ts.length?`<table><thead><tr><th>#</th><th>Team</th><th>League</th><th class="num">Seasons</th><th class="num">Games</th><th class="num">Total xG</th><th class="num">xG/game</th><th class="num">Avg xG/season</th></tr></thead><tbody>${ts.map((t,i)=>`<tr><td>${i+1}</td><td><strong>${esc(display(t.team))}</strong></td><td><span class="league-badge">${esc(t.league)}</span></td><td class="num">${t.seasonCount}</td><td class="num">${fmt(t.matches,0)}</td><td class="num">${fmt(t.xg)}</td><td class="num">${fmt(t.perGame)}</td><td class="num">${fmt(t.perSeason)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No matching records. Reset filters or disable the full-period coverage rule.</div>';}
 function dashboardUpdate(){const opts=options();currentRows=XG.filter(rows,opts);const s=metrics(currentRows);$('scope-description').textContent=`${year(opts.seasons[0])} to ${year(opts.seasons.at(-1))} · ${opts.league==='all'?'All five leagues':opts.league}`;
  $('result-note').innerHTML=s.rate?`<strong>${esc(display(s.rate.team))}</strong> leads this view with <strong>${fmt(s.rate.perGame)} xG per game</strong>. ${esc(display(s.season.team))} has the highest average season total at <strong>${fmt(s.season.perSeason)} xG</strong>. ${opts.complete?'All included teams appear in every selected season.':'Teams may have different numbers of seasons represented.'}`:'No eligible teams match this view. Try a different team, league or season range.';
  $('ranking-subtitle').textContent=metric==='perGame'?'Highest xG per game · combined xG ÷ combined games':'Highest average xG per season · combined xG ÷ seasons represented';$('trend-subtitle').textContent=(metric==='perGame'?'Season xG per game':'Season total xG')+' · top five teams in the current ranking';
  bars('ranking-chart',s.teams,metric);trend(currentRows,s.teams,opts.seasons,metric);table(s.teams);$('export-view').disabled=!currentRows.length;updateURL(opts);
 }
 function dashboard(){
  for(const id of ['start-season','end-season'])$(id).innerHTML=XG.SEASONS.map(s=>`<option value="${s}">${year(s)}</option>`).join('');
  $('league').innerHTML+=[...new Set(rows.map(r=>r.League))].sort().map(l=>`<option>${esc(l)}</option>`).join('');$('team-list').innerHTML=[...new Set(rows.map(r=>r.Team))].sort().map(t=>`<option value="${esc(t)}"></option>`).join('');
  const p=new URLSearchParams(location.search);$('start-season').value=XG.SEASONS.includes(p.get('start'))?p.get('start'):XG.SEASONS[0];$('end-season').value=XG.SEASONS.includes(p.get('end'))?p.get('end'):XG.SEASONS.at(-1);if([...$('league').options].some(o=>o.value===p.get('league')))$('league').value=p.get('league');$('team').value=p.get('team')||'';$('complete').checked=p.get('coverage')!=='any';metric=p.get('metric')==='perSeason'?'perSeason':'perGame';
  $('filters').addEventListener('submit',e=>e.preventDefault());$('filters').addEventListener('change',dashboardUpdate);$('team').addEventListener('input',dashboardUpdate);$('complete').addEventListener('change',dashboardUpdate);
  $('filters').addEventListener('reset',e=>{e.preventDefault();$('start-season').value=XG.SEASONS[0];$('end-season').value=XG.SEASONS.at(-1);$('league').value='all';$('team').value='';$('complete').checked=true;metric='perGame';$('table-sort').value='perGame';updateMetricButtons();dashboardUpdate();});
  function updateMetricButtons(){document.querySelectorAll('[data-metric]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.metric===metric)));}
  document.querySelectorAll('[data-metric]').forEach(b=>b.addEventListener('click',()=>{metric=b.dataset.metric;updateMetricButtons();dashboardUpdate();}));$('table-sort').addEventListener('change',()=>table(XG.aggregate(currentRows)));
  $('export-view').addEventListener('click',()=>{const headers=Object.keys(rows[0]),quote=v=>'"'+String(v).replace(/"/g,'""')+'"',csv=[headers.map(quote).join(','),...currentRows.map(r=>headers.map(k=>quote(r[k])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='xg_filtered_team_seasons.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});updateMetricButtons();dashboardUpdate();
 }
 Promise.all([fetch('data/team_seasons.csv').then(r=>{if(!r.ok)throw Error('CSV could not be loaded');return r.text();}),fetch('data/metadata.json').then(r=>r.json()),fetch('config.json').then(r=>r.json())]).then(([csv,m,c])=>{rows=XG.parseCSV(csv);meta=m;config=c;if(!rows.length||rows.some(r=>!Number.isFinite(r.Total_xG)||r.Matches_Played<=0))throw Error('The data file contains invalid xG or match counts.');if(document.body.dataset.page==='report')report();else dashboard();window.__XG_STATE__={rows,metadata:meta,defaultSummary:XG.summary(XG.filter(rows))};}).catch(e=>{const el=$('error');el.hidden=false;el.className='error';el.textContent=`The data could not be loaded: ${e.message}. Please refresh, or use the CSV download. Open this site through its hosted URL rather than opening the HTML file directly.`;console.error(e);});
})();
